print "  QDimensionGamma1";  // vs Magma's independent builtin formulas
for N in [1..50] do for k in [2..7] do
    assert QDimensionModularFormsGamma1(N,k) eq Dimension(ModularForms(Gamma1(N),k));
    assert QDimensionCuspFormsGamma1(N,k) eq DimensionCuspFormsGamma1(N,k);
    assert QDimensionNewCuspFormsGamma1(N,k) eq DimensionNewCuspFormsGamma1(N,k);
    assert QDimensionEisensteinFormsGamma1(N,k) eq Dimension(ModularForms(Gamma1(N),k)) - DimensionCuspFormsGamma1(N,k);
    assert QDimensionOldCuspFormsGamma1(N,k) eq DimensionCuspFormsGamma1(N,k) - DimensionNewCuspFormsGamma1(N,k);
end for; end for;

print "  DimensionCuspForms";  // Cohen-Oesterle vs Magma CuspForms (Q-dim = Galois-orbit sum)
for N in [1..24] do for n in [m:m in [1..N]|GCD(m,N) eq 1] do
    chi := DirichletCharacter(N,n);
    for k in [2..5] do assert QDimensionCuspForms(N,n,k) eq Dimension(CuspForms(chi,k)); end for;
end for; end for;
// deeper weights on levels exercising CO_delta/CO_nu branches (13.3 has chi(z4)=1, 13.12 has chi(z4)=-1, chi(z3)=1)
for t in [<13,3>,<13,12>,<25,7>,<16,3>,<27,26>,<36,35>,<32,3>] do
    chi := DirichletCharacter(t[1],t[2]);
    for k in [2..9] do assert QDimensionCuspForms(t[1],t[2],k) eq Dimension(CuspForms(chi,k)); end for;
end for;

print "  QDimensionEisensteinForms";  // vs Magma EisensteinSubspace, includes weight 1
for N in [1..20] do for n in [m:m in [1..N]|GCD(m,N) eq 1] do
    chi := DirichletCharacter(N,n);
    for k in [1..4] do
        d := Dimension(EisensteinSubspace(ModularForms(chi,k)));
        assert QDimensionEisensteinForms(chi,k) eq d;
        assert QDimensionEisensteinForms(N,n,k) eq d;
    end for;
end for; end for;
for N in [1..30] do
    assert QDimensionEisensteinForms(N,2) eq Dimension(EisensteinSubspace(ModularForms(Gamma0(N),2)));
end for;

print "  QDimensionNewEisensteinForms";
// divisor-sum identity E_k(N,chi) = sum_{cond|M|N} tau(N/M) E_k^new(M,chi_M); valid except k=2 trivial char
// (for k=2 trivial char the degeneracy images of E_2 old spaces overlap, so the identity fails mathematically)
for N in [1..30] do for n in [m:m in [1..N]|GCD(m,N) eq 1] do
    C := Conductor(N,n);
    for k in [1..4] do
        if k eq 2 and n eq 1 then continue; end if;
        assert QDimensionEisensteinForms(N,n,k) eq
               &+[QDimensionNewEisensteinForms(M,AssociatedCharacter(M,N,n),k)*#Divisors(N div M) where M := C*d : d in Divisors(N div C)];
    end for;
end for; end for;
// k=2 trivial char: hardcoded from LMFDB mf_newspaces.eis_new_dim
// (SELECT label,eis_new_dim FROM mf_newspaces WHERE label IN ('6.2.a','9.2.a','11.2.a','12.2.a','16.2.a','30.2.a','36.2.a','144.2.a'))
assert [QDimensionNewEisensteinForms(N,2) : N in [6,9,11,12,16,30,36,144]] eq [0,1,1,0,1,0,0,1];
// weight 1 new Eisenstein: LMFDB 23.1.b has eis_new_dim=1
assert QDimensionNewEisensteinForms(23,22,1) eq 1;
assert QDimensionNewEisensteinForms("23.22",1) eq 1;
assert QDimensionNewEisensteinForms(DirichletCharacter(23,22),1) eq 1;

print "  DimensionNewCuspForms";  // vs Magma NewSubspace, plus old+new=full and chi/label variants
for N in [1..20] do for n in [m:m in [1..N]|GCD(m,N) eq 1] do
    chi := DirichletCharacter(N,n);
    for k in [2..4] do
        d := Dimension(NewSubspace(CuspForms(chi,k)));
        assert QDimensionNewCuspForms(N,n,k) eq d;
        assert QDimensionNewCuspForms(chi,k) eq d;
        assert QDimensionOldCuspForms(N,n,k) eq QDimensionCuspForms(N,n,k) - d;
        assert QDimensionOldCuspForms(chi,k) eq QDimensionCuspForms(chi,k) - d;
    end for;
end for; end for;
for N in [1..60] do for k in [2..8] do  // Gamma0 old space vs builtin formulas
    assert QDimensionOldCuspForms(N,k) eq DimensionCuspFormsGamma0(N,k) - DimensionNewCuspFormsGamma0(N,k);
end for; end for;

print "  QDimension";
// dim ModSym(Gamma0(11),2) = 2g+e = 3 (g=1, one Eisenstein class), trivial character
assert QDimension(ModularSymbols(11,2)) eq 3;
// chi = 5.2 (order 4, degree 2): sign-0 space has dim 2 over Q(chi), Q-dimension 4
assert QDimension(ModularSymbols(DirichletCharacter(5,2),3)) eq 4;

print "  CuspSpaceCounts";  // brute-force count of (N,k[,orbit]) with N*k^2 <= B
