end for;
assert NumberOfGamma1CuspSpaces(B) eq bruteG1;
assert NumberOfGamma0CuspSpaces(B) eq bruteG0;
assert NumberOfNewspaces(B) eq bruteG1;
assert NumberOfNewspaces(B:SkipWeightOne:=true) eq brute2;
assert NumberOfNewspaces(B:TrivialCharOnly:=true,Maxk:=3) eq brute3;

